function shell_sort(my_list){
    let n = my_list.length;
    let gap = Math.floor(n/2);

    while (gap > 0) {
        for (let i = 0; i + gap < n; i++) {
            let temp = my_list[i];
            let j = i;
            while (j >= gap && my_list[j - gap] > temp) {
                my_list[j] = my_list[j - gap];
                j -= gap;
            }
            my_list[j] = temp;
        }
        gap = Math.floor(gap / 2);
    }
    return my_list;
}
